-- Comprobante de compra interno — NO es una factura electrónica DIAN válida (eso requiere un
-- proveedor tecnológico autorizado, ej. Factus, fase 3 pendiente). Sirve para probar el flujo
-- "el cliente ve algo después de pagar" mientras se conecta la facturación real. Uno por orden
-- aprobada, se genera automático en OrdenCompraService.aprobarOrden().
CREATE TABLE "comprobantes_compra" (
  "id_comprobante" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "id_orden_compra" BIGINT NOT NULL UNIQUE,
  "fecha_emision" TIMESTAMP NOT NULL DEFAULT now()
);

ALTER TABLE "comprobantes_compra" ADD FOREIGN KEY ("id_orden_compra") REFERENCES "ordenes_compra" ("id_orden_compra") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
